GRANT SELECT ON ALL TABLES IN SCHEMA public TO dsa_seats_ingest,dsa_seats_release_preflight; DO $$ DECLARE t record; BEGIN FOR t IN SELECT c.table_name FROM information_schema.columns c JOIN information_schema.tables x USING(table_schema,table_name) WHERE c.table_schema='public' AND c.column_name='release_id' AND x.table_type='BASE TABLE' AND c.table_name NOT IN('release_preflight_proofs','data_releases') LOOP EXECUTE format('GRANT INSERT,UPDATE,DELETE ON public.%I TO dsa_seats_ingest',t.table_name); END LOOP; END $$; GRANT INSERT(id,label,status,source_cutoff,created_at,previous_release_id) ON public.data_releases TO dsa_seats_ingest; REVOKE ALL ON public.release_preflight_proofs FROM dsa_seats_ingest,dsa_seats_web,dsa_seats_release_operator,dsa_seats_release_preflight;
CREATE OR REPLACE VIEW public.public_map_artifacts WITH(security_barrier=true) AS SELECT r.id release_id,gv.id geography_id,mar.raw_store_kind,mar.store_identity,mar.object_key,mar.sha256,mar.byte_size,mar.version_id,mar.etag FROM public.data_releases r JOIN public.map_artifacts ma ON ma.release_id=r.id JOIN public.geography_versions gv ON gv.release_id=ma.release_id AND gv.id=ma.geography_version_id JOIN public.map_artifact_receipts mar ON mar.release_id=ma.release_id AND mar.map_artifact_id=ma.id WHERE r.status='published' OR(r.status='retired' AND r.published_at IS NOT NULL);
ALTER VIEW public.public_map_artifacts OWNER TO dsa_seats_migration_owner; GRANT SELECT ON public.public_map_artifacts TO dsa_seats_web;
DO $$ DECLARE t record; BEGIN
 FOR t IN SELECT c.table_name FROM information_schema.columns c JOIN information_schema.tables x USING(table_schema,table_name) WHERE c.table_schema='public' AND c.column_name='release_id' AND x.table_type='BASE TABLE' AND c.table_name NOT IN('release_preflight_proofs','data_releases') LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.table_name); EXECUTE format('CREATE POLICY ingest_catalog_read ON public.%I FOR SELECT TO dsa_seats_ingest USING(true)',t.table_name); EXECUTE format('CREATE POLICY preflight_catalog_read ON public.%I FOR SELECT TO dsa_seats_release_preflight USING(true)',t.table_name); EXECUTE format('CREATE POLICY ingest_candidate_only ON public.%I FOR ALL TO dsa_seats_ingest USING(EXISTS(SELECT 1 FROM public.data_releases r WHERE r.id=release_id AND r.status=''candidate'')) WITH CHECK(EXISTS(SELECT 1 FROM public.data_releases r WHERE r.id=release_id AND r.status=''candidate''))',t.table_name); EXECUTE format('CREATE POLICY web_published_history ON public.%I FOR SELECT TO dsa_seats_web USING(EXISTS(SELECT 1 FROM public.data_releases r WHERE r.id=release_id AND (r.status=''published'' OR(r.status=''retired'' AND r.published_at IS NOT NULL))))',t.table_name);
 END LOOP; END $$;
ALTER TABLE public.data_releases ENABLE ROW LEVEL SECURITY; CREATE POLICY ingest_candidate_insert ON public.data_releases FOR INSERT TO dsa_seats_ingest WITH CHECK(status='candidate'); CREATE POLICY ingest_catalog_read ON public.data_releases FOR SELECT TO dsa_seats_ingest USING(true); CREATE POLICY preflight_catalog_read ON public.data_releases FOR SELECT TO dsa_seats_release_preflight USING(true); CREATE POLICY web_published_history ON public.data_releases FOR SELECT TO dsa_seats_web USING(status='published' OR(status='retired' AND published_at IS NOT NULL));
